writes:
{
  "name": "Beer distribution game",
  "brief": {
    "situation": "You run one company in a four-stage supply chain for a single product. Downstream of you, customers buy from the retailer: {$inputs.weeks} weeks of it, and every week they want a whole number of cases between {$inputs.demand_min} and {$inputs.demand_max}, picked at random. Up the chain: retailer, wholesaler, distributor, factory. Each week every company ships what it can to the company just below it, then places an order on the company just above it; the factory puts a batch into production instead of ordering. Orders reach your supplier the following week, and shipments take {$inputs.ship_delay} weeks to arrive; production takes {$inputs.production_delay} weeks. Everyone starts with {$inputs.start_inventory} cases in stock and {$inputs.start_pipeline} cases already on the way on every link. Demand you cannot fill becomes backlog and must be shipped later. At the end of every week you pay {$inputs.holding_cost|money} for each case in stock and {$inputs.backlog_cost|money} for each case of backlog. The team's goal is the lowest total cost for all four companies together. You only ever see your own numbers: your stock, your backlog, the orders coming in to you and the deliveries arriving to you.",
    "rules": "Each week you take one turn. In it you may, in any order and any number of times: set an order for the week, or cancel it; ship cases to the company below you; put cases into production (factory only). Anything you leave unset is decided for you: at the end of your turn the week is settled with your standing order, your shipping rule and your production rule — your company ships as much as it can, oldest backlog first, and orders the number of cases your rule calls for. Shipping below you and ordering above you happen at the same moment for every company, so you act on the same picture as everyone else. Every case you ship lowers your stock; cases you ship beyond what a customer asks for add to that customer's stock. Shipments leave your supplier only when it has the stock and take {$inputs.ship_delay} weeks to arrive; orders you place reach your supplier next week. At the end of each week stock and backlog are counted and billed.",
    "roles": {
      "retailer": "You are the RETAILER. The customers come to you: each week they buy what they can from your stock, and anything you cannot hand over becomes your backlog and is shipped later. You order from the wholesaler, who sits just above you, and you receive their shipments after {$inputs.ship_delay} weeks.",
      "wholesaler": "You are the WHOLESALER. Your customer is the retailer, just below you: you ship to them what you can, and their unfilled orders become your backlog. You order from the distributor, just above you, and receive their shipments after {$inputs.ship_delay} weeks.",
      "distributor": "You are the DISTRIBUTOR. Your customer is the wholesaler, just below you. You ship to them what you can; their unfilled orders become your backlog. You order from the factory, just above you, and receive their shipments after {$inputs.ship_delay} weeks.",
      "factory": "You are the FACTORY. Your customer is the distributor, just below you. You ship to them what you can; their unfilled orders become your backlog. You have no supplier: instead you put batches into production, and each batch arrives in your stock {$inputs.production_delay} weeks later."
    }
  },
  "clock": {"rounds": "$inputs.weeks", "unit": "week"},
  "inputs": {
    "weeks": {"type": "int", "default": 20, "min": 1, "description": "How many weeks the game lasts."},
    "demand_min": {"type": "int", "default": 0, "min": 0, "description": "Lowest weekly customer demand, in cases."},
    "demand_max": {"type": "int", "default": 8, "min": 0, "description": "Highest weekly customer demand, in cases."},
    "start_inventory": {"type": "int", "default": 12, "min": 0, "description": "Cases in stock at every company at the start."},
    "start_pipeline": {"type": "int", "default": 4, "min": 0, "description": "Cases already on the way on each shipping link at the start."},
    "ship_delay": {"type": "int", "default": 2, "min": 0, "description": "Weeks a shipment takes to arrive."},
    "production_delay": {"type": "int", "default": 2, "min": 0, "description": "Weeks a production batch takes to arrive."},
    "holding_cost": {"type": "number", "default": 0.5, "min": 0, "description": "Cost per case in stock at the end of a week."},
    "backlog_cost": {"type": "number", "default": 1.0, "min": 0, "description": "Cost per case of backlog at the end of a week."},
    "max_order": {"type": "int", "default": 200, "min": 1, "description": "Most cases a company may order or put into production in one week."}
  },
  "world": {
    "week": 1,
    "demand": 0,
    "production_orders": [],
    "settled": []
  },
  "defs": {
    "shortage": {"args": ["company"], "expr": "$max(0, $company.backlog + $company.incoming - $company.stock)"},
    "shipment": {"args": ["company"], "expr": "$min($company.stock, $company.backlog + $company.incoming)"},
    "cost": {"args": ["company"], "expr": "$inputs.holding_cost * $company.stock + $inputs.backlog_cost * $company.backlog"},
    "wip": {"args": ["company"], "expr": "$sum(beer, $it.qty, $it.owner == $company.id and $it.stage == production)"},
    "onwater": {"args": ["company"], "expr": "$sum(beer, $it.qty, $it.owner == $company.id and $it.stage == shipping)"}
  },
  "types": {
    "company": {
      "agent": true,
      "props": {
        "role": {"type": "text", "default": "company"},
        "up": {"type": "text", "default": ""},
        "down": {"type": "text", "default": ""},
        "stock": {"type": "int", "default": "$inputs.start_inventory", "min": 0},
        "backlog": {"type": "int", "default": 0, "min": 0},
        "incoming": {"type": "int", "default": 0, "min": 0},
        "incoming_last": {"type": "int", "default": 0, "min": 0},
        "delivered": {"type": "int", "default": 0, "min": 0},
        "orders_out": {"type": "int", "default": 0, "min": 0},
        "order_rule": {"type": "int", "default": "$inputs.start_inventory", "min": 0, "max": "$inputs.max_order"},
        "ship_rule": {"type": "int", "default": 0, "min": 0},
        "production_rule": {"type": "int", "default": "$inputs.start_inventory", "min": 0, "max": "$inputs.max_order},
        "pending_order": {"type": "int", "default": -1, "min": -1, "max": "$inputs.max_order"},
        "pending_ship": {"type": "int", "default": -1, "min": -1},
        "pending_production": {"type": "int", "default": -1, "min": -1, "max": "$inputs.max_order"},
        "spent": {"type": "number", "default": 0, "min": 0},
        "round_cost": {"type": "number", "default": 0, "min": 0}
      }
    },
    "beer": {
      "props": {
        "owner": {"type": "text", "default": ""},
        "qty": {"type": "int", "default": 0, "min": 0},
        "stage": {"type": "text", "default": "shipping"},
        "arrives": {"type": "int", "default": 0, "min": 0}
      }
    }
  },
  "entities": {
    "retailer": {"type": "company", "name": "Retailer", "props": {"role": "retailer", "up": "wholesaler", "down": ""}},
    "wholesaler": {"type": "company", "name": "Wholesaler", "props": {"role": "wholesaler", "up": "distributor", "down": "retailer"}},
    "distributor": {"type": "company", "name": "Distributor", "props": {"role": "distributor", "up": "factory", "down": "wholesaler"}},
    "factory": {"type": "company", "name": "Factory", "props": {"role": "factory", "up": "", "down": "distributor"}}
  },
  "stages": [
    {
      "name": "decide",
      "turns": "simultaneous",
      "actions": ["order", "ship", "produce"],
      "order": "seat",
      "brief": "Week {$round} of {$inputs.weeks}. Set your order for the week, ship to the company below you, and (as the factory) start production. Anything you do not set is settled at the end of your turn with your standing rules.",
      "on_idle": [
        {"if": "$actor.pending_order < 0", "then": ["$actor.pending_order = $actor.order_rule"]},
        {"if": "$actor.pending_ship < 0", "then": ["$actor.pending_ship = $actor.ship_rule"]},
        {"if": "$actor.role == factory and $actor.pending_production < 0", "then": ["$actor.pending_production = $actor.production_rule"]}
      ],
      "on_turn_end": ["$actor.settled = $actor.pending_order >= 0 and $actor.pending_ship >= 0 and ($actor.role != factory or $actor.pending_production >= 0)"]
    },
    {
      "name": "settle",
      "turns": "sequential",
      "actions": ["replenish"],
      "on_enter": [
        "$world.week = $round",
        {"each": "company", "do": ["$it.settled = $it.pending_order >= 0 and $it.pending_ship >= 0 and ($it.role != factory or $it.pending_production >= 0)"]},
        "$world.settled = $map(company, $it.id)",
        {"each": "company", "do": [
          "$it.incoming_last = $it.incoming",
          "$it.incoming = $it.incoming + $it.pending_order",
          "$it.orders_out = $it.pending_order",
          {"if": "$it.role == factory", "then": [
            "$it.delivered = $it.pending_production",
            "$it.production_rule = $it.pending_production",
            "$it.pending_production = -1"
          ], "else": [
            "$it.delivered = $min($it.pending_ship, $it.stock)",
            {"if": "$entity($it.up).pending_ship < 0", "then": ["$entity($it.up).pending_ship = $it.delivered"]}
          ]},
          {"create": "beer", "name": "Order {$it.id} w{$round}", "props": {"owner": "$it.up", "qty": "$it.pending_order", "stage": "order", "arrives": "$round + 1"}}
        ]},
        {"each": "beer", "where": "$it.stage == shipping and $it.arrives == $round", "do": ["$entity($it.owner).stock = $entity($it.owner).stock + $it.qty", {"remove": "$it"}]},
        {"each": "beer", "where": "$it.stage == production and $it.arrives == $round", "do": ["$entity($it.owner).stock = $entity($it.owner).stock + $it.qty", {"remove": "$it"}]}
      ],
      "on_turn_end": [
        "$world.settled = $filter($world.settled, $it != $actor.id)",
        {"if": "$len($world.settled) == 0", "then": [
          {"each": "beer", "where": "$it.stage == order and $it.arrives == $round + 1", "do": ["$entity($it.owner).incoming = $entity($it.owner).incoming + $it.qty", {"remove": "$it"}]},
          {"each": "beer", "where": "$it.stage == shipping", "do": ["$it.arrives = $it.arrives + 1"]},
          {"each": "beer", "where": "$it.stage == production", "do": ["$it.arrives = $it.arrives + 1"]}
        ]}
      ]
    }
  ],
  "actions": {
    "order": {
      "by": "company",
      "description": "Place this week's order on the company above you (the factory: the batch to put into production). It replaces any order you already set this week.",
      "params": {"amount": {"type": "int", "min": 0, "max": "$inputs.max_order", "description": "Cases ordered."}},
      "do": [
        "$actor.pending_order = $params.amount",
        "$actor.order_rule = $params.amount",
        {"if": "$actor.role == factory", "then": ["$actor.pending_production = $params.amount"]}
      ],
      "outcome": "You set your order for week {$round} to {$params.amount} cases."
    },
    "ship": {
      "by": "company",
      "description": "Set how many cases to ship to the company below you this week. It replaces any shipping you already set this week. You can only ship what you have in stock; the rest stays as backlog.",
      "params": {"amount": {"type": "int", "min": 0, "max": "$actor.stock", "description": "Cases shipped."}},
      "do": ["$actor.pending_ship = $params.amount", "$actor.ship_rule = $params.amount"],
      "outcome": "You will ship {$params.amount} cases to {$actor.down} this week."
    },
    "produce": {
      "by": "factory",
      "description": "Set the batch the factory puts into production this week. It replaces any batch you already set this week, and the cases arrive in your stock {$inputs.production_delay} weeks later.",
      "params": {"amount": {"type": "int", "min": 0, "max": "$inputs.max_order", "description": "Cases started."}},
      "do": ["$actor.pending_production = $params.amount", "$actor.production_rule = $params.amount", "$actor.pending_order = $params.amount"],
      "outcome": "You put {$params.amount} cases into production this week."
    },
    "replenish": {
      "by": "company",
      "description": "Fill in for a company that set nothing: ship what it can, keep its standing order and start the factory's standing batch.",
      "when": [{"expr": "not $actor.settled", "why": "You already settled this week."}],
      "do": [
        {"if": "$actor.pending_ship < 0", "then": ["$actor.pending_ship = $actor.ship_rule"]},
        {"if": "$actor.role == factory", "then": [
          {"if": "$actor.pending_production < 0", "then": ["$actor.pending_production = $actor.production_rule"]}
        ], "else": [
          {"if": "$actor.pending_order < 0", "then": ["$actor.pending_order = $actor.order_rule"]}
        ]}
      ],
      "outcome": "Your week is settled with the standing rules."
    }
  },
  "events": [
    {
      "name": "customer demand",
      "phase": "start",
      "do": ["$world.demand = $randint($inputs.demand_min, $inputs.demand_max)", "$entity(retailer).incoming = $entity(retailer).incoming + $world.demand"],
      "say": "Customers want {$world.demand} cases from the retailer this week."
    },
    {
      "name": "billing",
      "phase": "end",
      "do": [
        {"each": "company", "do": ["$it.round_cost = $inputs.holding_cost * $it.stock + $inputs.backlog_cost * $it.backlog", "$it.spent = $it.spent + $it.round_cost"]}
      ]
    }
  ],
  "views": {
    "dashboard": {
      "title": "Your company this week",
      "show": "Week {$round} — {$actor.name} ({$actor.role}). Stock: {stock} cases. Backlog: {backlog} cases. Orders received this week: {$actor.incoming_last}. Deliveries arriving this week: {$actor.delivered}. Orders you placed last week: {$actor.orders_out}. Cost so far: {$actor.spent|money}. Order rule: {$actor.order_rule} cases a week. Ship rule: {$actor.ship_rule} cases a week."
    },
    "pipeline": {
      "title": "On its way to you",
      "of": "$filter(beer, $it.owner == $actor.id and $it.stage == shipping)",
      "sort": "$it.arrives",
      "show": "Arriving in week {$it.arrives}: {$it.qty} cases"
    },
    "inproduction": {
      "title": "In production for you (factory)",
      "when": "$actor.role == factory",
      "of": "$filter(beer, $it.owner == $actor.id and $it.stage == production)",
      "sort": "$it.arrives",
      "show": "Finished in week {$it.arrives}: {$it.qty} cases"
    },
    "orders": {
      "title": "Orders that have reached you",
      "of": "$filter(beer, $it.owner == $actor.id and $it.stage == order and $it.arrives <= $round + 1)",
      "sort": "$it.arrives",
      "show": "Order placed in week {$it.arrives} arrives: {$it.qty} cases"
    }
  },
  "metrics": {
    "customer_demand": "$world.demand",
    "factory_order": "$entity(factory).delivered",
    "team_cost": "$sum(company, $it.round_cost)",
    "total_cost": "$sum(company, $it.spent)"
  },
  "outputs": {
    "customer_demand": {"expr": "$series.customer_demand", "type": "list", "description": "Cases customers demanded each week, in week order."},
    "factory_orders": {"expr": "$series.factory_order", "type": "list", "description": "Cases the factory put into production each week, in week order."},
    "costs_by_role": {"expr": "$dict(company, $it.role, $it.spent)", "type": "map", "format": "money", "description": "Total cost per company."},
    "total_team_cost": {"expr": "$sum(company, $it.spent)", "type": "number", "format": "money", "description": "All four companies' costs together."},
    "bullwhip_ratio": {"expr": "$variance($series.factory_order) / $variance($series.customer_demand)", "type": "number", "description": "Variance of the factory's weekly production orders divided by the variance of weekly customer demand."}
  },
  "invariants": [
    {"expr": "$all(company, $it.stock >= 0 and $it.backlog >= 0)", "why": "Stock and backlog can never go negative."},
    {"expr": "$all(beer, $it.qty >= 0)", "why": "No negative shipments or orders."}
  ],
  "policies": {
    "order_8": {
      "rules": [
        {"when": "$actor.role == factory", "do": "produce", "with": {"amount": 8}},
        {"do": "order", "with": {"amount": 8}}
      ]
    },
    "order_upstream": {
      "rules": [
        {"when": "$actor.role == factory", "do": "produce", "with": {"amount": "$actor.incoming_last + $actor.backlog - $actor.stock + $actor.orders_out"}},
        {"do": "order", "with": {"amount": "$actor.incoming_last + $actor.backlog - $actor.stock + $actor.orders_out"}}
      ]
    },
    "order_rule_only": {
      "rules": [
        {"when": "$actor.role == factory", "do": "produce", "with": {"amount": "$actor.production_rule"}},
        {"do": "order", "with": {"amount": "$actor.order_rule"}}
      ]
    }
  }
}
